import sympy as S
from fractions import Fraction as F
from itertools import product
from .authoring import maker,finish
from .common import section
q=maker('inequalities-domains',['attainable equality','domain restrictions','integer balancing'])
x=S.Symbol('x',real=True)
p=[
q(1,r'Positive real numbers x,y have sum 10. What is the largest possible xy?',25,[(100,'Square the sum without cross-term accounting.'),(50,'Use twice the maximum product.'),(24,'Assume the variables must be distinct integers.'),(20,'Choose an unbalanced pair.')],[r'From (x-y)²≥0, we get (x+y)²≥4xy.',r'Thus xy≤100/4=25.',r'Equality is attained at x=y=5, which satisfies the domain.'],['A square gives a universal nonnegative expression.' ,'Check the equality case after obtaining a bound.'],'Prove and attain a fixed-sum product bound.',lambda:(10/2)**2,'Independent completed-square form xy=25-(x-5)².',2),
q(2,r'Positive real numbers x,y,z satisfy x+y+z=12. What is the least possible $1/x+1/y+1/z$?',F(3,4),[(F(1,4),'Keep only one of the three equal reciprocal terms.'),(F(1,12),'Use the reciprocal of the total.'),(F(3,2),'Double the sharp lower bound.'),(1,'Assume integer variables must be unequal.')],[r'Cauchy–Schwarz gives (x+y+z)(1/x+1/y+1/z)≥(1+1+1)²=9.',r'The reciprocal sum is therefore at least 9/12=3/4.',r'Equality requires x=y=z=4 and is feasible, proving the minimum.'],['Pair square roots with reciprocal square roots in Cauchy–Schwarz.' ,'Determine whether equality is compatible with the sum constraint.'],'Match an inequality to a reciprocal target and verify equality.',lambda:3*S.Rational(1,4),'Equality witness plus Cauchy–Schwarz lower-bound certificate.'),
q(3,r'For x>0, what is the least possible value of $x+9/x$?',6,[(3,'Use the geometric mean without its factor two.'),(9,'Optimize only one term.'),(10,'Choose x=1 without proving it is best.'),(0,'Ignore positivity and the reciprocal constraint.')],[r'AM–GM gives x+9/x≥2√9=6.',r'Equality requires x=9/x, hence x=3 in the positive domain.',r'The value six is attained there.'],['The product of the two terms is constant.' ,'Solve the equality condition using the stated sign restriction.'],'Use a constant-product sum bound.',lambda:(lambda t:t+9/t)(S.Integer(3)),'Independent identity x+9/x-6=(x-3)²/x.',2),
q(4,r'Positive real numbers x,y satisfy x+y=1. What is the largest possible $xy^2$?',F(4,27),[(F(1,8),'Assume x=y without accounting for the repeated y factor.'),(F(1,27),'Forget the factor four after splitting y.'),(F(1,4),'Maximize xy and then ignore the extra y.'),(F(2,27),'Lose one of the two half-y factors.')],[r'The three positive terms x,y/2,y/2 sum to one.',r'AM–GM gives x(y/2)²≤(1/3)³, so xy²≤4/27.',r'Equality occurs at x=1/3,y=2/3, which meets the original constraint.'],['Split the repeated variable into equal pieces.' ,'Apply a three-term inequality with a fixed sum.'],'Choose weighted equality proportions rather than assuming symmetry.',lambda:S.expand(x*(1-x)**2).subs(x,S.Rational(1,3)),'Independent derivative factorization (1-x)(1-3x) confirms the interior maximum.'),
q(5,r'Positive real numbers x,y,z satisfy x+y+z=15 and $(x+y)(y+z)(z+x)=8xyz$. Find $x^2+y^2+z^2$.',75,[(225,'Use the squared sum without subtracting cross terms.'),(150,'Lose the factor two in the cross-term relation.'),(25,'Report one squared variable.'),(125,'Use a cube instead of a sum of squares.')],[r'Each factor obeys x+y≥2√(xy), and similarly for the other two.',r'The product is at least 8xyz. The given equality forces equality in all three positive-factor inequalities, so x=y=z.',r'The sum makes each variable five; the requested sum of squares is 75.'],['Compare each factor with twice the geometric mean of its terms.' ,'Equality of the positive product forces every individual lower bound to be tight.'],'Extract a unique configuration from simultaneous equality cases.',lambda:sum(t*t for t in [5,5,5]),'Equality conditions force the sole positive triple; direct substitution verifies both constraints.'),
q(6,r'For real x for which it is defined, what is the greatest value of $\sqrt{x+5}+\sqrt{5-x}$?',2*S.sqrt(5),[(S.sqrt(10),'Combine square roots by adding radicands.'),(S.sqrt(5),'Keep only one radical at the equality point x=0.'),(10,'Use the radicands rather than their square roots.'),(4*S.sqrt(5),'Double-count the two terms after squaring.')],[r'The domain is -5≤x≤5. Squaring the nonnegative expression gives 10+2√(25-x²).',r'This is at most 20 because x²≥0.',r'The maximum is √20=2√5, attained at x=0.'],['Establish the radical domain before squaring.' ,'The product of the radicands simplifies to a difference of squares.'],'Use a domain-safe square to expose a maximum.',lambda:S.sqrt(5)+S.sqrt(5),'Independent Cauchy bound (√(x+5)+√(5-x))²≤2·10, with equality x=0.',suffix='-choices-v2'),
q(7,r'Find the sum of all real solutions of $\sqrt{x+6}=x$.',3,[(1,'Keep both roots of the squared equation.'),(-2,'Keep only the extraneous negative root.'),(5,'Take absolute values of both algebraic roots.'),(6,'Use the radicand shift as the solution.')],[r'The left side is nonnegative, so any solution must have x≥0.',r'Squaring gives x²-x-6=0, with candidates x=3 and x=-2.',r'Only x=3 satisfies the original sign condition and equation, so the sum is three.'],['A square root has a fixed sign.' ,'Treat roots of the squared equation as candidates, then substitute.'],'Reject extraneous roots introduced by squaring.',lambda:sum(S.solveset(S.sqrt(x+6)-x,x,domain=S.S.Reals)),'Independent real solution-set computation.',2),
q(8,r'What is the product of the real solutions of $|x-2|+|x+4|=10$?',-24,[(6,'Report the constant minimum distance.'),(-8,'Use the two breakpoints as the solutions.'),(24,'Lose the sign of the negative solution.'),(-12,'Miss one factor of two in an outside interval.')],[r'Between -4 and 2, the sum is constantly six, so no solution lies there.',r'For x≥2 the equation is 2x+2=10, giving x=4. For x≤-4 it is -2x-2=10, giving x=-6.',r'The product is 4(-6)=-24. Both candidates lie in their assumed intervals.'],['Split the line at the two absolute-value breakpoints.' ,'Check whether the middle interval contributes any solutions.'],'Solve an absolute-value equation with interval consistency.',lambda:S.prod(S.solveset(S.Abs(x-2)+S.Abs(x+4)-10,x,domain=S.S.Reals)),'Independent real solution-set computation.'),
q(9,r'The set of real x satisfying $\lfloor x\rfloor+\lfloor2x\rfloor=10$ is an interval. What is its length?',F(1,2),[(1,'Treat both floors as constant across a full unit interval.'),(F(1,3),'Replace the floor sum by floor(3x).'),(2,'Double the interval instead of halving it.'),(0,'Assume only an integer solution is possible.')],[r'Write x=n+f with integer n and 0≤f<1. The equation becomes 3n+floor(2f)=10.',r'The last floor is zero or one, so n=3 and floor(2f)=1.',r'Thus 1/2≤f<1, giving x in [7/2,4), of length 1/2.'],['Separate integer and fractional parts.' ,'The doubled fractional part has only two possible floor values.'],'Reduce a floor equation to a finite residue choice and an interval.',lambda:sum(S.floor(S.Rational(k,1000))+S.floor(S.Rational(2*k,1000))==10 for k in range(3000,4000))/1000,'Independent rational-grid interval check; exact endpoint proof establishes the continuous interval.'),
q(10,r'For how many integers k with 0≤k≤30 does $\lfloor k/10\rfloor+\lfloor1-k/10\rfloor=0$?',27,[(31,'Ignore the exceptional integer inputs.'),(30,'Exclude only zero.'),(28,'Miss one endpoint with integer input.'),(4,'Count the exceptional inputs rather than the valid ones.')],[r'For noninteger t, writing t=n+f with 0<f<1 gives floor(t)+floor(1-t)=n-n=0.',r'For integer t, the sum is t+(1-t)=1.',r'Among 31 values of k, the four multiples 0,10,20,30 are excluded, leaving 27.'],['Compare integer and noninteger inputs separately.' ,'The endpoints can be exceptional too.'],'Handle boundary discontinuities in a floor identity.',lambda:sum(S.floor(S.Rational(k,10))+S.floor(1-S.Rational(k,10))==0 for k in range(31)),level=2),
q(11,r'For how many integers k with 1≤k≤10 does $t^2-2kt+k+2$ have two distinct positive real roots?',8,[(9,'Include the repeated-root case k=2.'),(10,'Use only positive sum and product.'),(2,'Count parameter endpoints instead of feasible values.'),(7,'Exclude k=3 despite its valid distinct roots.')],[r'The discriminant is 4(k²-k-2)=4(k-2)(k+1), which is positive in the stated range exactly when k>2.',r'For these k, the root sum 2k and product k+2 are positive. Real roots with positive product have the same sign, and their positive sum makes both positive.',r'Thus k=3,4,...,10, giving eight values.'],['Separate reality and distinctness from the sign of the roots.' ,'Use discriminant and Vieta together.'],'Combine a domain condition with coefficient-based root signs.',lambda:sum((lambda roots:len(roots)==2 and all(r.is_real and r>0 for r in roots))(S.solve(x*x-2*k*x+k+2,x)) for k in range(1,11)),'Independent exact root checks for all ten parameters.'),
q(12,r'How many integers x in [-5,5] satisfy $(x-1)/(x+2)>0$?',7,[(8,'Include the zero numerator at x=1.'),(9,'Include the undefined point x=-2 as well.'),(4,'Keep only the interval above one.'),(3,'Keep only the interval below minus two.')],[r'The numerator and denominator must have the same sign.',r'This occurs for x<-2 or x>1; x=-2 is undefined and x=1 gives zero.',r'The integers are -5,-4,-3,2,3,4,5, totaling seven.'],['Mark both the numerator root and the denominator root.' ,'A strict inequality excludes zeros as well as undefined points.'],'Use a sign chart with explicit domain exclusions.',lambda:sum(x!=-2 and F(x-1,x+2)>0 for x in range(-5,6))),
q(13,r'For real x in [2,5], what is the least possible value of $x^2+4/x^2$?',5,[(4,'Use an AM–GM equality point outside the interval.'),(F(629,25),'Use the upper endpoint instead of minimizing.'),(8,'Assume both terms are at least four.'),(F(145,36),'Evaluate at x=3/2, which lies outside the allowed interval.')],[r'AM–GM gives a lower bound four, but equality requires x=√2, outside the allowed interval.',r'For x≥2, $x^2+4/x^2-5=(x^2-1)(x^2-4)/x^2\ge0$.',r'Equality is attained at x=2, so the true minimum is five.'],['Check the equality point of the usual AM–GM bound.' ,'Compare the expression to its value at the nearest allowed endpoint.'],'Reject an unattainable inequality bound and sharpen it on the domain.',lambda:(x*x+4/x**2).subs(x,2),'Independent derivative 2x-8/x³ is positive throughout [2,5].',suffix='-choices-v2'),
q(14,r'Positive integers x,y,z satisfy x+y+z=11. What is the largest possible xyz?',48,[(S.Rational(1331,27),'Use the continuous AM–GM equality value, which needs noninteger variables.'),(45,'Use 3,3,5 without balancing.'),(40,'Use 2,4,5.'),(36,'Use 2,3,6.')],[r'If two positive entries differ by at least two, transfer one from the larger to the smaller.',r'Their product increases because (a+1)(b-1)-ab=b-a-1>0, while the sum and third positive factor are unchanged.',r'At a maximum, entries differ by at most one. They must therefore be 3,4,4, giving product 48.'],['An integer maximum must be attained by a feasible triple.' ,'Compare the product before and after balancing two unequal entries.'],'Prove integer balancing with a local improvement.',lambda:max(a*b*c for a in range(1,10) for b in range(1,10) for c in range(1,10) if a+b+c==11))]
e=[
q(101,r'Positive real numbers a,b satisfy a+b=8. What is the least possible $1/a+1/b$?',F(1,2),[(F(1,8),'Invert the sum.'),(F(1,4),'Report only one reciprocal at equality.'),(1,'Use an unbalanced pair without optimization.'),(F(3,4),'Confuse this two-variable constraint with a different three-variable bound.')],[r'Combine the fractions: 1/a+1/b=(a+b)/(ab)=8/(ab). Minimizing the reciprocal sum therefore means maximizing ab.',r'The identity (a-b)²≥0 gives ab≤16, with equality at a=b=4.',r'Thus the target is at least 8/16=1/2, and the equality pair is positive and satisfies the sum.',r'The direction reverses when passing from a positive denominator to its reciprocal. Writing that step explicitly prevents turning an upper bound on ab into the wrong kind of bound on the target.'],['Use a common denominator before choosing an inequality.' ,'The numerator is fixed and the denominator is positive.'],'Transform an objective and preserve inequality direction.',lambda:S.Rational(1,4)+S.Rational(1,4),'Independent Cauchy bound (a+b)(1/a+1/b)≥4.',2),
q(102,r'What is the least value of $|x-1|+|x-7|$ over real x?',6,[(0,'Try to make both distances zero simultaneously.'),(3,'Report the midpoint’s distance to one endpoint.'),(8,'Evaluate at a point outside the minimizing interval.'),(12,'Double-count the fixed endpoint distance.')],[r'The expression is the sum of distances from x to the points 1 and 7 on a line.',r'The triangle inequality makes it at least the distance between those endpoints, which is six.',r'Every x in [1,7] attains six; outside that interval, moving away increases both-distance sum.',r'Equality need not specify one point. Recording the full minimizing interval is useful when a second constraint is added later.'],['Interpret the absolute values as distances.' ,'Determine all points lying between the endpoints.'],'Identify a full equality set in a geometric inequality.',lambda:S.Abs(x-1).subs(x,4)+S.Abs(x-7).subs(x,4),'Piecewise formulas verify the bound on all three intervals.',2)]
for record in p:
 record['family']=record['id'].removesuffix('-choices-v2')
finish('inequalities-domains','Inequalities, equality cases & admissible roots','Algebra','inequalities floor polynomial-structure',40,'590–608',
 [r'An inequality gives a bound, but an optimization problem asks whether that bound can occur under the actual constraints. Equality cases, integer restrictions, radical signs, and excluded denominators are therefore central parts of the solution.',r'This study emphasizes choosing an inequality from the target expression, then checking its equality conditions against every constraint. The same discipline applies when algebraic transformations create candidate roots that may not solve the original equation.'],
 [section('Choose the inequality from the structure',r'A fixed positive sum suggests a product bound, while a fixed positive product suggests a sum bound. The elementary identity (x-y)²≥0 gives (x+y)²≥4xy and exposes equality directly. For reciprocal sums, combine fractions or use Cauchy–Schwarz so that the known sum appears as a factor.',r'A repeated variable in a product changes the equality proportions. To maximize xy² with x+y fixed, split y into two equal terms before applying three-term AM–GM. Equality then requires x=y/2, not x=y. The number of repeated factors determines the useful weighting.',r'If a product of positive quantities equals a product of individual lower bounds, every factor must meet its bound. This can force simultaneous equalities and determine a configuration without solving a large polynomial system. Positivity is essential: it makes any strict factor inequality produce a strict product inequality.'),
 section('The domain decides whether equality is available',r'AM–GM may provide a lower bound attained at a point outside a specified interval. In that case it is a valid bound but not the answer to the minimum problem. Check the interval and compare the expression with an attainable endpoint value, perhaps by factoring the difference.',r'For integer variables, the continuous equal-variable configuration may be impossible. A local balancing move supplies a discrete proof: moving one unit from a larger positive entry to a smaller one increases their product when the gap is at least two. At an integer maximum, the entries must be as equal as the sum permits.',r'For sums of distances, equality in the triangle inequality can occur on an entire segment. Do not assume every extremum has a unique equality point. A later condition may select one point from that interval, or exclude the entire equality set.'),
 section('Track equivalence through transformations',r'Squaring an equation preserves every original solution but can introduce new ones because it forgets signs. State the radical domain and the sign of the other side first, solve the squared equation, and substitute every candidate into the original statement.',r'For rational inequalities, numerator zeros and denominator zeros both split the number line, but only the denominator zeros are undefined. A strict inequality excludes numerator zeros as well. A sign chart avoids multiplying by an expression whose sign may change.',r'Floor expressions are controlled by integer and fractional parts. Write x=n+f with 0≤f<1; a small multiple of f has only finitely many floor values. Preserve open and closed endpoints when reconstructing the interval. In polynomial parameter problems, distinct real roots and positive roots are separate demands: combine a strict discriminant condition with Vieta’s sum and product signs.')],
 ['Match inequalities to an objective and derive their equality conditions.','Check attainability under interval, positivity, and integer constraints.','Solve transformed equations and inequalities without losing domains or endpoints.'],
 [r'Expand (x-y)²≥0 to derive the two-variable product bound and its equality case.',r'Compare (a+1)(b-1) with ab to prove integer balancing.',r'Write x=n+f and enumerate the possible floor values of the bounded fractional part.'],
 'A sharp inequality on a larger domain can be unattainable on the problem’s domain. Verify equality before calling a bound a minimum or maximum.',e,p,
 dict(prompt=r'For x≥3, AM–GM gives x+4/x≥4. Is four the minimum on this domain? Find and justify the actual minimum.',answer=r'No. The minimum is $13/3$, attained at x=3.',steps=[r'The AM–GM equality point is x=2, which is excluded.',r'For x≥3, $x+4/x-13/3=(x-3)(3x-4)/(3x)\ge0$.']),
 ['weighted AM–GM','Cauchy reciprocal bounds','integer balancing','domain-safe transformations'],
 [(r'\frac{a_1+\cdots+a_n}{n}\ge(a_1\cdots a_n)^{1/n}','Arithmetic–geometric mean','bounding a positive product by a fixed sum or a sum by a fixed product','The $a_i$ are nonnegative; equality holds when all are equal.'),(r'(\sum x_i)(\sum 1/x_i)\ge n^2','Reciprocal Cauchy bound','bounding a reciprocal sum when the original positive sum is fixed','Every $x_i$ is positive; equality requires all $x_i$ equal.'),(r'|x-a|+|x-b|\ge|a-b|','Line-distance bound','minimizing a sum of distances to two points on a line','Equality holds exactly when x lies between a and b, including the endpoints.'),(r'\Delta=b^2-4ac','Quadratic discriminant','checking whether a quadratic has distinct real roots before imposing root signs','$a\\ne0$; $\\Delta>0$ means two distinct real roots, while $\\Delta=0$ gives a repeated root.')], 'inequalities')
